import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const n="/assets/070101.CnOoVVCA.png",_=JSON.parse('{"title":"行情初始化链路","description":"行情起来之后如何恢复交易对盘口与曲线，再打开推送；不要求读者懂启动框架细节。","frontmatter":{"title":"行情初始化链路","description":"行情起来之后如何恢复交易对盘口与曲线，再打开推送；不要求读者懂启动框架细节。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070507"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070507"}],["meta",{"property":"og:title","content":"行情初始化链路 · TGEX"}],["meta",{"property":"og:description","content":"行情起来之后如何恢复交易对盘口与曲线，再打开推送；不要求读者懂启动框架细节。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"行情初始化链路 · TGEX"}],["meta",{"name":"twitter:description","content":"行情起来之后如何恢复交易对盘口与曲线，再打开推送；不要求读者懂启动框架细节。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"行情初始化链路\\",\\"description\\":\\"行情起来之后如何恢复交易对盘口与曲线，再打开推送；不要求读者懂启动框架细节。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070507\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070507\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070507.md","filePath":"07.现货手册/05.核心流程/07.行情初始化链路.md"}'),i={name:"pages/070507.md"};function d(p,t,h,s,l,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="行情初始化链路" tabindex="-1">行情初始化链路 <a class="header-anchor" href="#行情初始化链路" aria-label="Permalink to &quot;行情初始化链路&quot;">​</a></h1><div class="doc-lead">行情起来之后：先判断盘口与曲线从哪恢复并装进内存，再挂上事件与推送，最后打开定时任务和对外推送通道。</div><p align="center"><img src="'+n+'" alt="行情初始化链路"></p><p>下文按上图节点展开。请先分清几层「看起来像好了」：</p><table tabindex="0"><thead><tr><th>状态</th><th>实际表示</th></tr></thead><tbody><tr><td>进程已起来</td><td>框架级就绪，不等于盘口都齐</td></tr><tr><td>热路径行情已装齐</td><td>内存里已有交易对、深度、K 线等，读行情基本可用</td></tr><tr><td>推送通道已打开</td><td>客户端可以连上收推送；冷恢复时部分交易对仍可能在后台装</td></tr><tr><td>定时任务已打开</td><td>生成 K 线、核对交易对一类任务才会真正跑</td></tr></tbody></table><p><strong>进程起来 ≠ 推送已开 ≠ 每个交易对深度都齐。</strong></p><h2 id="_1-预热汇率等轻量数据" tabindex="-1">1. 预热汇率等轻量数据 <a class="header-anchor" href="#_1-预热汇率等轻量数据" aria-label="Permalink to &quot;1. 预热汇率等轻量数据&quot;">​</a></h2><p>先装与交易对 K 线无关的轻量数据（如第三方汇率），为后面折算与展示做准备。</p><h2 id="_2-判断缓存里是否已有交易对行情" tabindex="-1">2. 判断缓存里是否已有交易对行情 <a class="header-anchor" href="#_2-判断缓存里是否已有交易对行情" aria-label="Permalink to &quot;2. 判断缓存里是否已有交易对行情&quot;">​</a></h2><p>看本地热缓存里是否已有交易对行情快照：有则走热恢复；没有则走冷恢复或备份重建。</p><h2 id="_3a-热恢复-缓存已有" tabindex="-1">3a. 热恢复（缓存已有） <a class="header-anchor" href="#_3a-热恢复-缓存已有" aria-label="Permalink to &quot;3a. 热恢复（缓存已有）&quot;">​</a></h2><ol><li>确认有启用中的交易对；一个都没有则后面无从装行情。</li><li>把交易对、最新价、盘口结构等装进内存。</li><li>按交易对装深度、各周期 K 线等，并标记「可以推」。</li><li>等这批热路径装齐，再往下开推送相关步骤。</li></ol><h2 id="_3b-冷恢复-备份-缓存没有" tabindex="-1">3b. 冷恢复 / 备份（缓存没有） <a class="header-anchor" href="#_3b-冷恢复-备份-缓存没有" aria-label="Permalink to &quot;3b. 冷恢复 / 备份（缓存没有）&quot;">​</a></h2><p>有备份则把备份灌回缓存与内存；没有备份则从源头重建交易对列表，再按交易对陆续装深度、K 线、成交历史。</p><p>冷恢复时，服务可能<strong>很快就能对外</strong>，但各交易对仍在后台陆续装齐——会出现「已经能连，部分交易对深度暂时为空」的窗口。</p><h2 id="_4-挂上行情相关内部事件" tabindex="-1">4. 挂上行情相关内部事件 <a class="header-anchor" href="#_4-挂上行情相关内部事件" aria-label="Permalink to &quot;4. 挂上行情相关内部事件&quot;">​</a></h2><p>挂上生成 K 线、落库一类内部事件。此时定时任务开关可能仍关着，真正执行要等到后面打开。</p><h2 id="_5-开始按订阅推送" tabindex="-1">5. 开始按订阅推送 <a class="header-anchor" href="#_5-开始按订阅推送" aria-label="Permalink to &quot;5. 开始按订阅推送&quot;">​</a></h2><p>按客户端订阅推送深度、最新价、成交、K 线，以及首页榜单一类低频内容。<br> 推送通道若尚未打开，任务可能空转一会儿，属正常现象。</p><h2 id="_6-打开定时任务-·-打开行情推送通道" tabindex="-1">6. 打开定时任务 · 打开行情推送通道 <a class="header-anchor" href="#_6-打开定时任务-·-打开行情推送通道" aria-label="Permalink to &quot;6. 打开定时任务 · 打开行情推送通道&quot;">​</a></h2><p>打开本机行情定时任务；必要时同步外部行情源；打开面向客户端的推送通道；再补币种名称、折算、人气榜一类展示数据。</p><h2 id="就绪怎么理解" tabindex="-1">就绪怎么理解 <a class="header-anchor" href="#就绪怎么理解" aria-label="Permalink to &quot;就绪怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问法</th><th>答案</th></tr></thead><tbody><tr><td>进程起来了吗？</td><td>框架就绪即可回答</td></tr><tr><td>读内存行情靠谱吗？</td><td>看热路径是否装齐（热恢复通常更齐）</td></tr><tr><td>客户端能连上推送吗？</td><td>看推送通道是否已开</td></tr><tr><td>每个交易对深度都有了吗？</td><td>冷恢复时可能还没有，要按交易对看</td></tr></tbody></table><p>运维探活常常只确认「交易对列表能不能读到」，<strong>不</strong>等于推送通道已开。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><p>盘口与曲线如何推到客户端，见<a href="/pages/070509">行情推送流程</a>。撮合侧恢复盘口见<a href="/pages/070505">撮合初始化链路</a>。</p><p>同组：<a href="/pages/070505">撮合初始化链路</a> · <a href="/pages/070504">委托初始化链路</a> · <a href="/pages/070506">账务初始化链路</a> · <a href="/pages/070509">行情推送流程</a></p>',28)])])}const m=e(i,[["render",d]]);export{_ as __pageData,m as default};
